mapper.select:
select BS.SUBJECT_NO as subjectNo, BS.SUBJECT_NAME as subjectName, BS.FSUBJECT_ID as fsubjectId, BS.SUBJECT_TYPE as subjectType, BS.SUBJECT_LEVEL as subjectLevel, BS.CREATE_USER as createUser, BS.CREATE_DEPT as createDept, BS.CREATE_TIME as createTime, BS.UPDATE_USER as updateUser, BS.UPDATE_TIME as updateTime, BS.UPDATE_TIME as updateDate, BS.DATA_SOURCE as dataSource, BS.STATUS as status, BS.REMARK as remark, BS.DESCRIBE as describe from BOK_SUBJECT BS
BS.SUBJECT_LEVEL = #{subjectLevel}
AND BS.FSUBJECT_ID = #{fsubjectId}
AND BS.SUBJECT_NO like #{subjectNo} || '%'
AND BS.SUBJECT_NAME like '%' || #{subjectName} || '%'
AND BS.SUBJECT_TYPE = #{subjectType}
AND BS.STATUS = #{status}
order by BS.BOOKSET_ID,BS.SUBJECT_NO,BS.SUBJECT_LEVEL
